204	export class GraphPointer<R extends UnresolvedRule = UnresolvedRule> {
205	  node: GraphNode<R>;
206	  parent?: GraphPointer;
207	  #valid?: boolean;
208	  id: string;
209	
210	  constructor(node: GraphNode<R>, parent?: GraphPointer) {
211	    if (node === undefined) {
212	      throw new Error('Node is undefined');
213	    }
214	    this.node = node;
215	    this.parent = parent;
216	    this.id = parent ? `${parent.id}-${node.id}` : node.id;
217	  }
218	
219	  *resolve(resolved = false): IterableIterator<ResolvedGraphPointer> {
220	    /*
221	     * 1. If the current node is an end node, and the pointer has a parent, return the parent's `fetchNext`; else return nothing.
222	     * 2. If the current node is a rule ref, yield the referenced nodes, _unless_ resolved is true, in which case it returns next.
223	     * 3. If the current node is a char or range, we go to the next node. If none exists, throw an error.
224	     */
225	    if (isGraphPointerRuleRef(this)) {
226	      if (resolved) {
227	        if (!this.node.next) {
228	          throw new Error(`No next node: ${JSON.stringify(this.node)}`);
229	        }
230	        yield* new GraphPointer(this.node.next, this.parent).resolve();
231	      } else {
232	
233	        for (const node of this.node.rule.nodes) {
234	          yield* new GraphPointer(node, this).resolve();
235	        }
236	      }
237	    } else if (isGraphPointerRuleEnd(this)) {
238	      if (!this.parent) {
239	        yield this;
240	      } else {
241	        yield* this.parent.resolve(true);
242	      }
243	    } else if (isGraphPointerRuleChar(this) || isGraphPointerRuleCharExclude(this)) {
244	      yield this;
245	    } else {
246	      throw new Error(`Unknown rule: ${JSON.stringify(this.node.rule)}`);
247	    }
248	  }
249	
250	  *fetchNext(): IterableIterator<ResolvedGraphPointer> {
251	    // if this pointer is invalid, then we don't return any new pointers
252	    if (this.#valid === false) {
253	      return;
254	    }
255	
256	    // if this pointer is an end node, we return the parent's next node. If no parent exists,
257	    // we return nothing, since it's the end of the line.
258	    if (isRuleEnd(this.node.rule)) {
259	      if (this.parent) {
260	        yield* this.parent.fetchNext();
261	      }
262	    } else {
263	      if (!this.node.next) {
264	        throw new Error(`No next node: ${JSON.stringify(this.node)}`);
265	      }
266	      const pointer = new GraphPointer(this.node.next, this.parent);
267	      yield* pointer.resolve();
268	    }
269	  }
270	
271	  get rule() {
272	    return this.node.rule;
273	  }
