                col(
                    "".join(
                        "".join(col(from_char_code(val), Color.YELLOW) for val in v)
                        if is_range(v)
                        else _get_char(v)
                        for v in rule.value
                    ),
                    Color.YELLOW,
                ),
                col("]", Color.GRAY),
            ]
        )
    elif is_rule_ref(rule):
        parts.append(
            col("Ref(", Color.GRAY) + col(f"{rule.value}", Color.GREEN) + col(")", Color.GRAY)
        )
    else:
        parts.append(col(rule.type.value, Color.YELLOW))

    if pointers:
