import json
import random
import subprocess
import sys

TOKENS = [
    '"a"', '"b"', '"ab"', '"\\n"', '"\\t"', '"\\x41"', '"\\u00e9"', '"\\\\"', '""',
    "[a-z]", "[A-Z]", "[0-9]", "[^a-z]", "[abc]", "[a-c0-9]", "[^\\n]", "[-a]", "[a-]",
    "*", "+", "?", "|", "(", ")", " ", "\n", "foo", "bar", "root", "#c\n", "::=",
]

NAMES = ["root", "foo", "bar", "baz"]


def random_grammar(rng):
    parts = []
    for name in rng.sample(NAMES, rng.randint(1, len(NAMES))):
        body = "".join(rng.choice(TOKENS) for _ in range(rng.randint(1, 7)))
        parts.append(f"{name} ::= {body}")
    return "\n".join(parts)


def random_input(rng):
    alphabet = "ab c\nAZ09é\\\"[]|*+?()"
    return "".join(rng.choice(alphabet) for _ in range(rng.randint(0, 6)))


def run(cases):
    payload = json.dumps(cases)
    js = subprocess.run(
        ["node", "--experimental-transform-types", "--no-warnings", "/tmp/jsref/run.mjs", payload],
        capture_output=True, text=True,
    )
    py = subprocess.run(
        [sys.executable, "/tmp/jsref/run.py", payload], capture_output=True, text=True
    )
    if js.returncode:
        return None, ("JS crashed", js.stderr[-1500:])
    if py.returncode:
        return None, ("PY crashed", py.stderr[-3000:])
    return (json.loads(js.stdout), json.loads(py.stdout)), None


def main():
    seed = int(sys.argv[1]) if len(sys.argv) > 1 else 0
    total = int(sys.argv[2]) if len(sys.argv) > 2 else 400
    rng = random.Random(seed)
    cases = [
        {"grammar": random_grammar(rng), "inputs": [random_input(rng) for _ in range(3)]}
        for _ in range(total)
    ]
    fails = 0
    batch = 50
    for start in range(0, len(cases), batch):
        chunk = cases[start : start + batch]
        result, err = run(chunk)
        if err:
            print(err[0])
            print(err[1])
            return 1
        j, p = result
        for i, (a, b) in enumerate(zip(j, p)):
            if a != b:
                fails += 1
                if fails <= 5:
                    print(f"--- mismatch (case {start + i})")
                    print("  grammar:", json.dumps(chunk[i]["grammar"]))
                    print("  inputs :", json.dumps(chunk[i]["inputs"]))
                    print("  js:", json.dumps(a)[:900])
                    print("  py:", json.dumps(b)[:900])
    print(f"\nseed={seed}: {len(cases)} fuzz cases, {fails} mismatches")
    return 1 if fails else 0


sys.exit(main())

